/**
 * Events stream (lld/webhooks.md §5.1, spec 0.3.0 `streamEvents`). Pure rules:
 *
 * - `parseStreamTypes`: the `types` filter (`*` default; same rule as endpoint `enabled_events`, the first
 *   entry that is neither `*` nor a webhook type is reported, `ping` included).
 * - `resumeOutcome`: whether a resume cursor is honoured (`replay`) or the stream sends `event: reset`
 *   (`cursor_unknown` / `cursor_expired`) and continues live only.
 * - `TailState`: the live tail's bookkeeping. Event ids are UUIDv7 generated by ingest when the row is
 *   built, so id order is generation order, not commit order. The stream reads rows older than the
 *   **settle window** (2 s after insert) in id order above its cursor (`forward`), and re-reads the
 *   **10 s of ids behind its cursor** (`late`) for a row whose transaction committed after a higher id
 *   was already sent. Ids sent inside the re-read window are remembered (and excluded from the re-read)
 *   until the window moves past them, so no id is sent twice; a row committing more than ~10 s after its
 *   id was generated can be missed (ingest transactions are short), the client catches up with
 *   `GET /v1/events` like after a reset.
 *
 * UUIDs are compared as lowercase strings: their byte order (what Postgres uses) is their string order.
 */
import { EVENT_STREAM_MAX_CONCURRENT, EVENT_STREAM_MAX_SECONDS } from "@nearpay-money/spec";
import { normalizeEnabledEvents } from "../endpoint/events.js";

/** Rows younger than this (since insert) are not streamed yet: their lower-id neighbours may still commit. */
export const SETTLE_MS = 2_000;
/** Ids up to this far behind the cursor are re-read for rows that committed late. */
export const REREAD_MS = 10_000;
/** Rows per query (replay and live). */
export const PAGE_SIZE = 100;
/** Each stream polls this often; `NOTIFY events_<mode>` wakes it early. */
export const POLL_MS = 1_000;
/** A stream ends after this long (`ready.expires_at`); the client reconnects with `Last-Event-ID`. */
export const MAX_DURATION_MS = EVENT_STREAM_MAX_SECONDS * 1_000;
/** Concurrent streams per (account, mode). */
export const MAX_STREAMS = EVENT_STREAM_MAX_CONCURRENT;
/** A client keeping more than this unsent… */
export const MAX_BUFFERED_BYTES = 1024 * 1024;
/** …for this long is closed. */
export const SLOW_CLIENT_MS = 30_000;
/** Concurrency slots expire unless refreshed (each heartbeat), so a crashed replica frees its slots. */
export const SLOT_TTL_MS = 30_000;
/** `Retry-After` of `429 rate_limited` (too many streams). */
export const RETRY_AFTER_S = 5;

export type StreamTypes = { readonly ok: readonly string[] } | { readonly unknown: string; readonly index: number };

/** `types` query value → the types a stream carries (`["*"]` = all, `ping` included). */
export function parseStreamTypes(raw: string | undefined): StreamTypes {
  if (raw === undefined) return { ok: ["*"] };
  return normalizeEnabledEvents(raw.split(","));
}

/** The SQL filter of a stream's types: null = every type. */
export function typeFilter(types: readonly string[]): readonly string[] | null {
  return types.includes("*") ? null : types;
}

export type ResumeOutcome =
  | { readonly kind: "replay" }
  | { readonly kind: "reset"; readonly reason: "cursor_unknown" | "cursor_expired" };

/**
 * A cursor is honoured when it is an event of the caller's account and mode inside the retention
 * window. An event older than retention — or an id this account does not have whose UUIDv7 time is older
 * than retention (the row was purged) — is `cursor_expired`; anything else is `cursor_unknown`.
 */
export function resumeOutcome(
  found: { readonly created_at: Date } | null,
  cursorUuid: string,
  now: number,
  retentionMs: number,
): ResumeOutcome {
  const since = now - retentionMs;
  if (found)
    return found.created_at.getTime() >= since ? { kind: "replay" } : { kind: "reset", reason: "cursor_expired" };
  const t = uuidTimeMs(cursorUuid);
  return t !== null && t < since
    ? { kind: "reset", reason: "cursor_expired" }
    : { kind: "reset", reason: "cursor_unknown" };
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

/** Millisecond timestamp of a UUIDv7 (first 48 bits), or null for another UUID version. */
export function uuidTimeMs(uuid: string): number | null {
  const u = uuid.toLowerCase();
  if (!UUID_RE.test(u) || u[14] !== "7") return null;
  return Number.parseInt(u.slice(0, 8) + u.slice(9, 13), 16);
}

/** The lowest UUID whose UUIDv7 time is `ms` (a comparison bound, not a valid v7 id); `ms` < 0 → nil UUID. */
export function uuidFloor(ms: number): string {
  const hex = Math.max(0, Math.min(Math.floor(ms), 0xffff_ffff_ffff))
    .toString(16)
    .padStart(12, "0");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-0000-0000-000000000000`;
}

const max = (a: string, b: string) => (a > b ? a : b);

/**
 * Live-tail bookkeeping of one stream. `origin` is the first cursor: the resume cursor, or the UUID
 * floor of the open instant for a live-only stream. Nothing at or below `origin` is ever sent.
 */
export class TailState {
  readonly origin: string;
  #cursor: string;
  /** Sent ids above the re-read floor, ascending. */
  #sent: string[] = [];

  constructor(origin: string) {
    this.origin = origin.toLowerCase();
    this.#cursor = this.origin;
  }

  /** Highest id sent (or `origin`). `forward` reads above it. */
  get cursor(): string {
    return this.#cursor;
  }

  /** `late` reads ids in `(floor, cursor]`, excluding `sentAboveFloor`. */
  get floor(): string {
    const t = uuidTimeMs(this.#cursor);
    return t === null ? this.origin : max(this.origin, uuidFloor(t - REREAD_MS));
  }

  /** Ids already sent inside the re-read window (excluded from `late`). */
  get sentAboveFloor(): readonly string[] {
    return this.#sent;
  }

  /**
   * Takes rows read by `late` or `forward` (any order) and returns those to send, in id order: never one
   * at or below `origin` or the floor, never one sent before. Records them and moves the cursor.
   */
  accept<R extends { readonly id: string }>(rows: readonly R[]): R[] {
    const floor = this.floor;
    const seen = new Set(this.#sent);
    const out: R[] = [];
    for (const r of [...rows].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))) {
      const id = r.id.toLowerCase();
      if (id <= floor || id <= this.origin || seen.has(id)) continue;
      seen.add(id);
      out.push(r);
      if (id > this.#cursor) this.#cursor = id;
    }
    const next = this.floor;
    this.#sent = [...seen].filter((id) => id > next).sort();
    return out;
  }
}
